// Framework scaffold content generators (mirrors backend scaffold.go)

export function getInstallScript(lang: string, projectName: string): string {
  switch (lang.toLowerCase()) {
    case 'python':
      return `#!/bin/bash
# Install script for ${projectName}
# Generated by pom-app

set -e

echo "Setting up Python Playwright project..."

# Create virtual environment
python3 -m venv venv
source venv/bin/activate

# Install dependencies
pip install -r requirements.txt

# Install Playwright browsers
playwright install chromium

echo ""
echo "Setup complete!"
echo "Activate virtual environment: source venv/bin/activate"
echo "Run tests: pytest"`;

    case 'java':
      return `#!/bin/bash
# Install script for ${projectName}
# Generated by pom-app

set -e

echo "Setting up Java Selenium project..."

# Build with Maven and download dependencies
mvn clean install -DskipTests

echo ""
echo "Setup complete!"
echo "Run tests: mvn test"`;

    default:
      return `#!/bin/bash
# Install script for ${projectName}
# Generated by pom-app

echo "Please install dependencies manually for this project."`;
  }
}

