// ── BDD Framework Helpers ──

export interface BddFrameworkInfo {
  name: string;        // e.g. "Behave"
  runner: string;      // e.g. "behave"
  configFile: string;  // e.g. "behave.ini"
  stepsDir: string;    // e.g. "features/steps/"
  hooksFile: string;   // e.g. "features/environment.py"
  featureDir: string;  // e.g. "features/"
}

const BDD_FRAMEWORKS: Record<string, BddFrameworkInfo> = {
  python: {
    name: 'Behave',
    runner: 'behave',
    configFile: 'behave.ini',
    stepsDir: 'features/steps/',
    hooksFile: 'features/environment.py',
    featureDir: 'features/',
  },
  java: {
    name: 'Cucumber',
    runner: 'mvn test -Dcucumber',
    configFile: 'pom.xml (cucumber deps)',
    stepsDir: 'src/test/java/steps/',
    hooksFile: 'src/test/java/steps/Hooks.java',
    featureDir: 'src/test/resources/features/',
  },
};

export function getBddFrameworkInfo(lang: string): BddFrameworkInfo | null {
  return BDD_FRAMEWORKS[lang.toLowerCase()] || null;
}

export function getBddRunCommand(lang: string): string {
  const info = getBddFrameworkInfo(lang);
  return info ? info.runner : '';
}

