export function getBddStepsPreview(lang: string): string {
  switch (lang.toLowerCase()) {
    case 'python':
      return `from behave import given, when, then
from pages.base_page import BasePage


@given('I am on the "{page_name}" page')
def step_navigate_to_page(context, page_name):
    context.page.goto(context.base_url)


@when('I fill "{field}" with "{value}"')
def step_fill_field(context, field, value):
    context.page.fill(f'[name="{field}"]', value)


@when('I click the "{button}" button')
def step_click_button(context, button):
    context.page.click(f'text={button}')


@then('I should see "{text}"')
def step_should_see_text(context, text):
    assert context.page.is_visible(f'text={text}')`;

    case 'java':
      return `import io.cucumber.java.en.*;
import com.microsoft.playwright.*;
import static org.testng.Assert.*;

public class CommonSteps {
    private Page page;

    @Given("I am on the {string} page")
    public void navigateToPage(String pageName) {
        page.navigate(System.getenv("BASE_URL"));
    }

    @When("I fill {string} with {string}")
    public void fillField(String field, String value) {
        page.fill("[name=\\"" + field + "\\"]", value);
    }

    @When("I click the {string} button")
    public void clickButton(String button) {
        page.click("text=" + button);
    }

    @Then("I should see {string}")
    public void shouldSeeText(String text) {
        assertTrue(page.isVisible("text=" + text));
    }
}`;

    default:
      return '';
  }
}

