export function getApiReadme(projectName: string, lang: string, endpoints: { method: string; path: string; name: string; expected_status: number }[]): string {
  const l = lang.toLowerCase();
  const langInfo: Record<string, { lang: string; client: string; runner: string; runCmd: string }> = {
    python: { lang: 'Python', client: 'requests', runner: 'pytest', runCmd: 'source venv/bin/activate\npytest' },
    java: { lang: 'Java 17', client: 'REST Assured', runner: 'TestNG', runCmd: 'mvn test' },
  };
  const info = langInfo[l] || { lang: lang, client: 'HTTP', runner: 'unknown', runCmd: '# run tests' };

  const endpointsTable = endpoints.length > 0
    ? endpoints.map((e) => `| ${e.method} | ${e.path} | ${e.name} | ${e.expected_status} |`).join('\n')
    : '| - | - | - | - |';

  return `# ${projectName}

> API Testing project generated by [pom-app](https://github.com/pom-app)

## Tech Stack

- **Language**: ${info.lang}
- **HTTP Client**: ${info.client}
- **Test Runner**: ${info.runner}
- **Reporting**: Allure

## Quick Start

\`\`\`bash
cp .env.example .env  # Edit with your values
chmod +x install.sh
./install.sh
\`\`\`

## Run Tests

\`\`\`bash
${info.runCmd}
\`\`\`

## Endpoints

| Method | Path | Name | Expected Status |
|--------|------|------|----------------|
${endpointsTable}

## Docker

\`\`\`bash
docker build -t api-tests .
docker run --env-file .env api-tests
\`\`\`

## CI/CD

GitHub Actions workflow included in \`.github/workflows/tests.yml\`.
Add \`BASE_URL\` and \`API_TOKEN\` to your repository secrets.`;
}

export function getApiBaseClient(lang: string, baseUrl: string): string {
  switch (lang.toLowerCase()) {
    case 'python':
      return `"""Base API client with session management."""
import os
import requests
from dotenv import load_dotenv

load_dotenv()

BASE_URL = os.getenv("BASE_URL", "${baseUrl}")


class BaseApiClient:
    """Base client for all API interactions."""

    def __init__(self):
        self.session = requests.Session()
        self.base_url = BASE_URL.rstrip("/")
        # Set default headers
        self.session.headers.update({
            "Content-Type": "application/json",
            "Accept": "application/json",
        })
        # Add auth token if available
        token = os.getenv("API_TOKEN")
        if token:
            self.session.headers["Authorization"] = f"Bearer {token}"
        api_key = os.getenv("API_KEY")
        if api_key:
            self.session.headers["X-API-Key"] = api_key

    def _url(self, path: str) -> str:
        return f"{self.base_url}{path}"

    def get(self, path: str, **kwargs) -> requests.Response:
        return self.session.get(self._url(path), **kwargs)

    def post(self, path: str, **kwargs) -> requests.Response:
        return self.session.post(self._url(path), **kwargs)

    def put(self, path: str, **kwargs) -> requests.Response:
        return self.session.put(self._url(path), **kwargs)

    def patch(self, path: str, **kwargs) -> requests.Response:
        return self.session.patch(self._url(path), **kwargs)

    def delete(self, path: str, **kwargs) -> requests.Response:
        return self.session.delete(self._url(path), **kwargs)

    def close(self):
        self.session.close()`;

    case 'java':
      return `package api;

import io.restassured.RestAssured;
import io.restassured.response.Response;
import io.restassured.specification.RequestSpecification;

import java.io.FileInputStream;
import java.util.Properties;

/**
 * Base client for all API interactions.
 */
public class BaseApiClient {

    protected final String baseUrl;
    protected final RequestSpecification requestSpec;

    public BaseApiClient() {
        Properties props = loadEnv();
        this.baseUrl = props.getProperty("BASE_URL", "${baseUrl}");
        String token = props.getProperty("API_TOKEN", "");
        String apiKey = props.getProperty("API_KEY", "");

        RestAssured.baseURI = baseUrl;

        requestSpec = RestAssured.given()
                .header("Content-Type", "application/json")
                .header("Accept", "application/json");

        if (!token.isEmpty()) {
            requestSpec.header("Authorization", "Bearer " + token);
        }
        if (!apiKey.isEmpty()) {
            requestSpec.header("X-API-Key", apiKey);
        }
    }

    protected Response get(String path) {
        return requestSpec.get(path);
    }

    protected Response post(String path, Object body) {
        return requestSpec.body(body).post(path);
    }

    protected Response put(String path, Object body) {
        return requestSpec.body(body).put(path);
    }

    protected Response patch(String path, Object body) {
        return requestSpec.body(body).patch(path);
    }

    protected Response delete(String path) {
        return requestSpec.delete(path);
    }

    private Properties loadEnv() {
        Properties props = new Properties();
        System.getenv().forEach(props::setProperty);
        try (FileInputStream fis = new FileInputStream(".env")) {
            props.load(fis);
        } catch (Exception ignored) {
        }
        return props;
    }
}`;

    default:
      return '';
  }
}

