export function getApiConftest(lang: string): string {
  switch (lang.toLowerCase()) {
    case 'python':
      return `"""Pytest fixtures for API testing."""
import pytest
from api.base_client import BaseApiClient


@pytest.fixture(scope="session")
def api_client():
    """Shared API client for the test session."""
    client = BaseApiClient()
    yield client
    client.close()`;

    case 'java':
      return `package base;

import io.restassured.RestAssured;
import io.restassured.specification.RequestSpecification;
import org.testng.annotations.BeforeClass;

import java.io.FileInputStream;
import java.util.Properties;

/**
 * Base class for all API tests.
 */
public class BaseApiTest {

    protected RequestSpecification requestSpec;

    @BeforeClass(alwaysRun = true)
    public void setupBase() {
        Properties props = loadEnv();
        String baseUrl = props.getProperty("BASE_URL", "");
        String token = props.getProperty("API_TOKEN", "");
        String apiKey = props.getProperty("API_KEY", "");

        RestAssured.baseURI = baseUrl;

        requestSpec = RestAssured.given()
                .header("Content-Type", "application/json")
                .header("Accept", "application/json");

        if (!token.isEmpty()) {
            requestSpec.header("Authorization", "Bearer " + token);
        }
        if (!apiKey.isEmpty()) {
            requestSpec.header("X-API-Key", apiKey);
        }
    }

    private Properties loadEnv() {
        Properties props = new Properties();
        System.getenv().forEach(props::setProperty);
        try (FileInputStream fis = new FileInputStream(".env")) {
            props.load(fis);
        } catch (Exception ignored) {
        }
        return props;
    }
}`;

    default:
      return '';
  }
}

export function getBddHooksPreview(lang: string): string {
  switch (lang.toLowerCase()) {
    case 'python':
      return `from playwright.sync_api import sync_playwright


def before_all(context):
    context.playwright = sync_playwright().start()
    context.browser = context.playwright.chromium.launch(headless=True)


def before_scenario(context, scenario):
    context.page = context.browser.new_page()
    context.base_url = os.environ.get("BASE_URL", "http://localhost")


def after_scenario(context, scenario):
    if context.page:
        context.page.close()


def after_all(context):
    context.browser.close()
    context.playwright.stop()`;

    case 'java':
      return `import io.cucumber.java.Before;
import io.cucumber.java.After;
import com.microsoft.playwright.*;

public class Hooks {
    private static Playwright playwright;
    private static Browser browser;
    private BrowserContext context;
    private Page page;

    @Before
    public void setUp() {
        playwright = Playwright.create();
        browser = playwright.chromium()
            .launch(new BrowserType.LaunchOptions().setHeadless(true));
        context = browser.newContext();
        page = context.newPage();
    }

    @After
    public void tearDown() {
        if (page != null) page.close();
        if (context != null) context.close();
        if (browser != null) browser.close();
        if (playwright != null) playwright.close();
    }
}`;

    default:
      return '';
  }
}
